<?php
require_once __DIR__ . '/_layout.php';requirePermission('invoices.manage');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$invoice=dbFetchOne("SELECT i.*,c.first_name,c.last_name,c.company_name,r.reference FROM invoices i JOIN customers c ON c.id=i.customer_id LEFT JOIN reservations r ON r.id=i.reservation_id WHERE i.id=? AND i.agency_id IN ($ph)",array_merge([$id],$ids));if(!$invoice){http_response_code(404);exit(t('validation.finance_not_found'));}
if(requestMethod()==='POST'){requireCsrfPost();try{$action=$_POST['action']??'';if($action==='issue')issueInvoice(['invoice_id'=>$id,'idempotency_key'=>$_POST['idempotency_key']??'']);elseif($action==='cancel')cancelInvoiceDraft(['invoice_id'=>$id,'reason'=>$_POST['reason']??'','idempotency_key'=>$_POST['idempotency_key']??'']);elseif($action==='credit')issueCreditNote(['invoice_id'=>$id,'amount'=>$_POST['amount']??'','reason'=>$_POST['reason']??'','idempotency_key'=>$_POST['idempotency_key']??'']);else throw new InvalidArgumentException(t('validation.invalid_action'));flash('success',t('message.invoice_updated'));}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Invoice operation failed');flash('danger',t('message.finance_failed'));}safeRedirect('invoice_detail.php?id='.$id);}
$items=dbFetchAll('SELECT * FROM invoice_items WHERE invoice_id=:id ORDER BY sort_order,id',['id'=>$id]);$credits=$invoice['invoice_type']==='invoice'?dbFetchAll("SELECT * FROM invoices WHERE original_invoice_id=:id AND invoice_type='credit_note' ORDER BY issued_at,id",['id'=>$id]):[];$balance=$invoice['invoice_type']==='invoice'?financeInvoiceBalance($id):null;backofficeHeader(t('page.invoice_detail.title'),'invoices.php');pageHeader('page.invoice_detail.title','page.invoice_detail.description',['breadcrumbs'=>[['label'=>'nav.finance','href'=>'finance.php'],['label'=>'nav.invoices','href'=>'invoices.php'],['label'=>$invoice['invoice_number']?:t('status.draft')]]]);?>
<div class="grid"><section class="card"><h2><?=isolatedValue($invoice['invoice_number']?:t('status.draft'),'reference-value')?></h2><dl class="detail-list"><dt><?=e(t('field.customer'))?></dt><dd><?=e($invoice['company_name']?:$invoice['first_name'].' '.$invoice['last_name'])?></dd><dt><?=e(t('field.reservation'))?></dt><dd><?=isolatedValue($invoice['reference'],'reference-value')?></dd><dt><?=e(t('field.total'))?></dt><dd><?=money($invoice['total_amount'],$invoice['currency'])?></dd><?php if($balance):?><dt><?=e(t('field.credited'))?></dt><dd><?=money(centsToMoney($balance['credited']),$invoice['currency'])?></dd><dt><?=e(t('field.paid'))?></dt><dd><?=money(centsToMoney($balance['paid']),$invoice['currency'])?></dd><dt><?=e(t('field.remaining'))?></dt><dd><?=money(centsToMoney($balance['remaining']),$invoice['currency'])?></dd><?php endif;?><dt><?=e(t('common.status'))?></dt><dd><?=statusBadge($invoice['status'])?></dd></dl><?php if($invoice['issued_at']):?><a class="btn secondary" target="_blank" rel="noopener" href="invoice_print.php?id=<?=e($id)?>"><?=e(t('common.print_pdf'))?></a><?php endif;?></section><section class="card"><h2><?=e(t('section.invoice_items'))?></h2><div class="table-wrap"><table><thead><tr><th><?=e(t('field.description'))?></th><th><?=e(t('field.quantity'))?></th><th><?=e(t('field.unit_price'))?></th><th><?=e(t('field.total'))?></th></tr></thead><tbody><?php foreach($items as$item):?><tr><td><?=e($item['description'])?></td><td><?=e($item['quantity'])?></td><td><?=money($item['unit_price'],$invoice['currency'])?></td><td><?=money($item['line_total'],$invoice['currency'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php if($invoice['status']==='draft'):?><section class="card"><div class="actions"><form method="post"><?=csrfField()?><?=financeIdempotencyField('invoice.issue')?><input type="hidden" name="action" value="issue"><button class="btn primary"><?=e(t('action.issue_invoice'))?></button></form><form method="post"><?=csrfField()?><?=financeIdempotencyField('invoice.cancel_draft')?><input type="hidden" name="action" value="cancel"><label><?=e(t('field.reason'))?><input name="reason" required maxlength="255"></label><button class="btn danger"><?=e(t('action.cancel_draft'))?></button></form></div></section><?php elseif($invoice['invoice_type']==='invoice'&&$invoice['status']!=='credited'):?><section class="card"><h2><?=e(t('action.issue_credit_note'))?></h2><form method="post"><?=csrfField()?><?=financeIdempotencyField('credit_note.issue')?><input type="hidden" name="action" value="credit"><label><?=e(t('field.amount'))?><input name="amount" inputmode="decimal" required></label><label><?=e(t('field.reason'))?><input name="reason" required maxlength="255"></label><button class="btn secondary"><?=e(t('action.issue_credit_note'))?></button></form></section><?php endif;?>
<?php if($credits):?><section class="card"><h2><?=e(t('section.credit_notes'))?></h2><div class="table-wrap"><table><thead><tr><th><?=e(t('field.number'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('field.reason'))?></th></tr></thead><tbody><?php foreach($credits as$credit):?><tr><td><a href="invoice_detail.php?id=<?=e($credit['id'])?>"><?=isolatedValue($credit['invoice_number'],'reference-value')?></a></td><td><?=money($credit['total_amount'],$credit['currency'])?></td><td><?=e($credit['credit_reason'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php backofficeFooter();
